% conformance testing framework of Peter Szabo and Peter Szeredi.
% Generated by lang/stralog/tests/mkiso.py: v(Name, Expected, Goal).

elk(X) :- moose(X).
:- dynamic(legs/2).
legs(A, 4) :- animal(A).
legs(octopus, 8).
legs(A, 6) :- insect(A).
legs(spider, 8).
legs(B, 2) :- bird(B).
:- dynamic(insect/1).
insect(ant).
insect(bee).
:- dynamic(foo/1).
foo(X) :- call(X) -> call(X).
foo(X) :- call(X), call(X).

v(iso_retract_1_01, true, (retract(legs(octopus, 8)))).
v(iso_retract_1_02, false, (retract(legs(spider, 6)))).
v(iso_retract_1_03, true(T == bird(X)), (retract((legs(X, 2) :- T)))).
v(iso_retract_1_05, false, (retract((legs(_X,_Y) :- _Z)))).
v(iso_retract_1_06, true(I == ant), (retract(insect(I)), retract(insect(bee)))).
v(iso_retract_1_08, true(A-B == call(C)-call(C)), (retract((foo(C) :- A -> B)))).
v(iso_retract_1_09, error(instantiation_error), (retract((_X :- in_eec(_Y))))).
v(iso_retract_1_10, error(type_error(callable,4)), (retract((4 :- _X)))).
v(lgt_retract_1_12, error(instantiation_error), (retract(_))).
v(eclipse_retract_1_14, false, (retract(mammal(_)))).
